int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_orphan *orphan;
    struct ext4_orphan *prev_orphan = NULL;
    int err = 0;

    if (!ext4_journal_has_feature_compression(sb))
        return 0;

    down_write(&sbi->s_orphan_lock);

    list_for_each_entry(orphan, &sbi->s_orphan, ei_list) {
        if (orphan->inum == inode->i_ino)
            break;
    }

    if (orphan && orphan->inum == inode->i_ino) {
        if (handle) {
            err = ext4_handle_dirty_metadata(handle, NULL, NULL);
            if (err) {
                up_write(&sbi->s_orphan_lock);
                return err;
            }
        }

        list_del(&orphan->ei_list);
        kfree(orphan);
    }

    up_write(&sbi->s_orphan_lock);

    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_sb_info *sbi = inode->i_sb->s_fs_info;
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_orphan *orphan;
    int err = 0;

    if (!ext4_journal_has_feature(sbi->s_journal, EXT4_FEATURE_COMPAT_HAS_JOURNAL)) {
        return -EINVAL;
    }

    mutex_lock(&sbi->s_orphan_lock);

    if (!ei->i_dtime) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -ENOENT;
    }

    orphan = ei->i_orphan;
    if (orphan) {
        list_del(&orphan->o_list);
        ei->i_orphan = NULL;
    }

    mutex_unlock(&sbi->s_orphan_lock);

    if (handle) {
        err = ext4_journal_dirty(handle, &sbi->s_orphan_lock);
        if (err < 0) {
            return err;
        }
    }

    return 0;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;
    int ret = 0;
    struct ext4_iloc iloc;
    struct buffer_head *bh;
    __u32 inum;
    __u32 count;

    if (EXT4_HAS_RO_COMPAT_FEATURE(sb, EXT4_FEATURE_RO_COMPAT_ORPHAN_FILE))
        return 0;

    mutex_lock(&sbi->s_orphan_lock);

    if (!ei->i_dtime) {
        ext4_error(sb, "ext4_orphan_del", -EINVAL, 0,
                   "Inode %lu has non-zero dtime",
                   inode->i_ino);
        mutex_unlock(&sbi->s_orphan_lock);
        return -EINVAL;
    }

    inum = cpu_to_le32(inode->i_ino);
    count = le32_to_cpu(sbi->s_orphan_count);

    if (count == 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        return 0;
    }

    if ((err = ext4_reserve_inode_write(handle, inode, &iloc)) != 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        return err;
    }

    bh = iloc.bh;

    if (count == 1) {
        ext4_set_orphan(sbi, NULL);
    } else {
        struct ext4_iloc iloc2;
        struct buffer_head *bh2;
        __u32 ino2;
        int i, found = 0;

        for (i = 1; i <= count; i++) {
            if ((err = ext4_read_inode_block(inode, i, &iloc2)) != 0) {
                ext4_brelse(bh);
                mutex_unlock(&sbi->s_orphan_lock);
                return err;
            }

            bh2 = iloc2.bh;
            ino2 = ext4_get_orphan(inode, bh2, i);

            if (ino2 == inode->i_ino) {
                int j;

                found = 1;
                for (j = i; j < count; j++) {
                    ino2 = ext4_get_orphan(inode, bh2, j + 1);
                    ext4_set_orphan(inode, bh2, j, ino2);
                }

                ext4_set_orphan(inode, bh2, count, 0);
                ext4_mark_buffer_dirty(handle, bh2);
                ext4_brelse(bh2);
                break;
            }

            ext4_brelse(bh2);
        }

        if (!found) {
            ext4_brelse(bh);
            mutex_unlock(&sbi->s_orphan_lock);
            return -ENOENT;
        }

        count--;
        ext4_set_orphan_count(inode, count);
    }

    ext4_mark_buffer_dirty(handle, bh);
    ext4_brelse(bh);
    mutex_unlock(&sbi->s_orphan_lock);
    return ret;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *es = &(EXT4_SB(inode->i_sb)->s_es);
    struct ext4_orphan *orphan;
    int err = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return 0;

    mutex_lock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    if (!ei->i_dtime && (ei->i_flags & EXT4_ORPHAN_FLAG)) {
        orphan = find_orphan(inode);
        if (!orphan) {
            mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
            return -EINVAL;
        }

        if (handle) {
            err = ext4_journal_get_write_access(handle, inode->i_sb,
                                                  orphan->bh, 0);
            if (err) {
                mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
                return err;
            }
        }

        remove_orphan(inode);
        ei->i_flags &= ~EXT4_ORPHAN_FLAG;

        if (handle) {
            err = ext4_handle_dirty_metadata(handle, inode, orphan->bh);
            if (err) {
                mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
                return err;
            }
        }
    }

    mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *o;
    int ret = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb))
        return 0;

    spin_lock(&sbi->s_orphan_lock);
    o = ei->i_orphan;
    if (o) {
        list_del_init(&ei->i_orphan->list);
        ei->i_orphan = NULL;
        if (handle) {
            ret = ext4_journal_dirty_metadata(handle, &o->list);
            if (ret < 0) {
                spin_unlock(&sbi->s_orphan_lock);
                return ret;
            }
        }
    }
    spin_unlock(&sbi->s_orphan_lock);

    return ret;
}
